  if (memberPoint.value < 10) {
    alert('금액이 부족합니다.')
    return;
  }
  if (confirm("10돌맹이로 오늘의 운세를 확인할까요?")) {

    const res = await apiPost('member.php', {
      mode: 'studentHopeInsert',
      idnt_code: sessionStorage.getItem('idnt_code'),
